with kept_keys as (select product_id, id from order_items except all select product_id, id from order_items where quantity != 3), reconciled as (select s.* from order_items s join kept_keys k on s.product_id = k.product_id and s.id = k.id) select order_id, count(distinct order_id) as distinct_order_ids, approx_percentile(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles, percentile_approx(unit_price, array(0.25, 0.5, 0.75)) as unit_price_quartiles, count(*) as row_count, percentile_approx(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles_2, avg(quantity) as avg_quantity from reconciled group by order_id having count(distinct order_id) > 1
